from __future__ import annotations

import logging
import time

from .tcp import TcpPdu
from .base import PduIdentificationType
from ..exceptions import PduConnectionError, BadResponse, BadDeviceStatus
from ..device_status import DeviceStatus


class Kikusui(TcpPdu):
    """Power switch module for Kikusui power switches
    It does not support port numbers, so all commands are sent to the single output."""

    DELAY = 1  # Delay after a power state change, to prevent damage

    def __init__(self, host: str, port: int = 5025, timeout: float = 5, retry_timeout: float = 10) -> None:
        super().__init__(host, port, timeout, retry_timeout)
        _vendor, _model, _serial, _version = self.get_idn()

        logging.info(
            f"IDN information is vendor: {_vendor}, model: {_model}, serial number: {_serial}, version: {_version}"
        )

    def get_idn(self) -> list:
        info = self.get_pdu_info()
        if info.identification_type != PduIdentificationType.SCPI_IDN:
            raise PduConnectionError("Failed to communicate with Kikusui device: no IDN")
        return [item.strip() for item in info.identifier.split(",")]

    def power_on(self, port=None) -> None:
        self._execute_cmd_with_retry_on_timeout("OUTP:STAT ON\r\n")
        time.sleep(self.DELAY)
        self._check_error()

    def power_off(self, port=None) -> None:
        self._execute_cmd_with_retry_on_timeout("OUTP:STAT OFF\r\n")
        time.sleep(self.DELAY)
        self._check_error()

    def set_voltage(self, port=None, voltage: float | None = None) -> None:
        if voltage is None:
            return
        current_voltage = self.get_voltage()
        if abs(current_voltage - voltage) > 0.1:
            self._execute_cmd_with_retry_on_timeout(f"VOLT {voltage:.2f}\r\n")
            time.sleep(0.1)
            self._check_error()

    def _get_measurement(self, command: str, measure_command: str, measurement_type: str) -> float:
        state = self._execute_cmd_with_retry_on_timeout("OUTP?\r\n")
        if state == "":
            raise BadDeviceStatus(f"Could not check {measurement_type}.")

        unit = "V" if measurement_type == "voltage" else "A"
        state = float(state)
        value = self._execute_cmd_with_retry_on_timeout(command).strip()

        if state == 0:
            logging.info(f"Kikusui set {measurement_type} is {value} {unit}.")
            return float(value)
        else:
            measured_value = self._execute_cmd_with_retry_on_timeout(measure_command).strip()
            logging.info(
                f"Kikusui set {measurement_type} is {float(value)} {unit} and "
                f"measured {measurement_type} is {float(measured_value)} {unit}."
            )
            return float(measured_value)

    def get_voltage(self, port=None) -> float:
        return self._get_measurement("VOLT?\r\n", "MEAS:VOLT?\r\n", "voltage")

    def get_current(self, port=None) -> float:
        return self._get_measurement("CURR?\r\n", "MEAS:CURR?\r\n", "current")

    def reset(self, ports=None, time_interval=10):
        self.power_off()
        time.sleep(time_interval)
        self.power_on()

    def get_port_status(self, port=None):
        state = self._execute_cmd_with_retry_on_timeout("OUTP?\r\n")
        if state == "":
            raise BadDeviceStatus("Could not check Kikusui power status.")

        state = float(state)
        voltage = self._execute_cmd_with_retry_on_timeout("VOLT?\r\n").strip()
        current = self._execute_cmd_with_retry_on_timeout("CURR?\r\n").strip()
        ovp = self._execute_cmd_with_retry_on_timeout("VOLT:PROT?\r\n").strip()

        settings_info = f"Set voltage is {voltage} V and current {current} A. Over voltage protection level is {ovp} V."

        if state == 0:
            logging.info(f"Kikusui power is OFF. {settings_info}")
            return DeviceStatus.OFF
        else:
            measured_voltage = self._execute_cmd_with_retry_on_timeout("MEAS:VOLT?\r\n").strip()
            measured_current = self._execute_cmd_with_retry_on_timeout("MEAS:CURR?\r\n").strip()

            measurements_info = f"Measured voltage is {measured_voltage} V and current {measured_current} A."
            logging.info(f"Kikusui power is ON. {settings_info} {measurements_info}")
            return DeviceStatus.ON

    def _check_error(self) -> None:
        tmp = self._execute_cmd_with_retry_on_timeout("SYST:ERR?\r\n")
        code = int(tmp.split(",")[0])
        if code != 0:
            raise BadResponse(f"{tmp}")

    def _parse_response(self, response):
        """Not implemented for this device - commands handle their own response parsing"""
        pass

    @property
    def _port_setting(self) -> dict:
        """Only to satisfy the contract of PDU abstraction"""
        return {
            DeviceStatus.OFF: "OFF",
            DeviceStatus.ON: "ON",
        }

    def _build_command(self, port, status):
        """Not implemented for this device - methods construct their own commands"""
        pass
